#!/usr/bin/env bash
# Context-length step-cost measurement (TASK97, CTXCOST_DESIGN.md): every
# (artifact, plan) lifecycle through run_multiturn.sh -- the multi-turn runner,
# server arguments and streaming path (as TASK92) -- with a 40 s window.
#
#   run_ctxcost.sh <RUN_DIR_ABS>
#
# Order: seeded shuffle (20262099) of BASE n in {1,2,4,8} and TUNED
# n in {1,2,4,8,16}, each x L in {512,1500,3000}; then two reproducibility
# repeats (TUNED n4 L1500, TUNED n8 L3000; tag ".rep2"). A failed lifecycle is
# retried once under "<tag>.retry1". Do not edit this file or anything it calls
# while it runs (KNOWN_PITFALLS 5).
set -uo pipefail
RUN="$1"
REPO=/home/rebel/continuum-npu
case "$RUN" in /*) ;; *) echo "RUN must be absolute"; exit 64 ;; esac
mkdir -p "$RUN"
S3="$REPO/experiments/npu/stage3"
PLANS="$S3/plans/ctxcost"
declare -A ART=(
  [BASE]="$REPO/models/Qwen3-4B-rbln-b8-s8192-d4-mb"
  [TUNED]="$REPO/models/Qwen3-4B-rbln-b16-s8192-d4-mb16"
)
git -C "$REPO" rev-parse HEAD >> "$RUN/git-head.txt"
git -C "$REPO" status --porcelain >> "$RUN/git-status.txt"
[ -f "$RUN/measurement-start.txt" ] || date -Is > "$RUN/measurement-start.txt"
rbln-stat > "$RUN/rbln-stat-before.$(date +%s).txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply.sh" status > "$RUN/patch-before.$(date +%s).txt" 2>&1

mapfile -t ITEMS < <(python3 - <<'PYEOF'
import random
items = [("BASE", f"ctx-n{n}-L{L}") for n in (1, 2, 4, 8) for L in (512, 1500, 3000)]
items += [("TUNED", f"ctx-n{n}-L{L}") for n in (1, 2, 4, 8, 16) for L in (512, 1500, 3000)]
random.Random(20262099).shuffle(items)
items += [("TUNED", "ctx-n4-L1500"), ("TUNED", "ctx-n8-L3000")]
seen = {}
for cfg, pid in items:
    seen[(cfg, pid)] = seen.get((cfg, pid), 0) + 1
    rep = "" if seen[(cfg, pid)] == 1 else ".rep2"
    print(cfg, pid, f"{cfg}.{pid}{rep}")
PYEOF
)

for item in "${ITEMS[@]}"; do
  set -- $item
  CFG="$1"; PID="$2"; TAG="$3"
  echo "=== $TAG $(date -Is)"
  bash "$S3/run_multiturn.sh" "$RUN" "$TAG" "${ART[$CFG]}" "$PLANS/$PID.json" stream 40
  if [ ! -f "$RUN/done.$TAG" ]; then
    echo "$TAG failed, retrying once"
    bash "$S3/run_multiturn.sh" "$RUN" "$TAG.retry1" "${ART[$CFG]}" "$PLANS/$PID.json" stream 40
  fi
done
date -Is > "$RUN/measurement-end.txt"
rbln-stat > "$RUN/rbln-stat-after.txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply.sh" status > "$RUN/patch-after.txt" 2>&1
echo "CTXCOST DONE"
